     6	CMD ["bun", "src/app.ts"]
=== deploy.sh
     1	#!/usr/bin/env bash
     2	set -euo pipefail
     3	gcloud tasks queues create sections --location us-central1 || true
     4	gcloud run deploy reports-service --source . --region us-central1 --allow-unauthenticated
=== migrations/001_reports.sql
     1	create table reports (
     2	  id text primary key,
     3	  company text not null,
     4	  status text not null default 'queued',
     5	  created_at timestamptz not null default now()
     6	);
     7	
     8	create table sections (
     9	  id text primary key,
    10	  report_id text not null references reports(id),
    11	  name text not null,
    12	  position int not null,
    13	  body text
    14	);
=== src/app.ts
     1	import { getReport, listSections } from "./db";
     2	import { handleGenerateSection } from "./worker";
     3	
     4	const json = (body: unknown, status = 200) =>
     5	  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
     6	
     7	export async function handle(req: Request): Promise<Response> {
     8	  const url = new URL(req.url);
     9	  if (req.method === "POST" && url.pathname === "/tasks/generate-section") return handleGenerateSection(req);
    10	  const m = url.pathname.match(/^\/reports\/([^/]+)$/);
    11	  if (req.method === "GET" && m) {
    12	    const report = await getReport(m[1]);
    13	    if (!report) return json({ error: "not found" }, 404);
    14	    return json({ ...report, sections: await listSections(m[1]) });
    15	  }
    16	  return json({ error: "not found" }, 404);
    17	}
    18	
    19	if (import.meta.main) Bun.serve({ port: Number(process.env.PORT ?? 8080), fetch: handle });
=== src/db.ts
     1	import { sql } from "bun";
     2	
     3	// Postgres (Cloud SQL). Schema in migrations/.
     4	export type Report = { id: string; company: string; status: string; created_at: string };
     5	
     6	export async function getReport(id: string): Promise<Report | undefined> {
     7	  const rows = await sql`select * from reports where id = ${id}`;
     8	  return rows[0];
     9	}
    10	
    11	export async function listSections(reportId: string) {
    12	  return sql`select id, name, body from sections where report_id = ${reportId} order by position`;
    13	}
    14	
    15	export async function saveSection(reportId: string, name: string, body: string) {
    16	  await sql`update sections set body = ${body} where report_id = ${reportId} and name = ${name}`;
    17	}
=== src/llm.ts
     1	// Takes 20-60 s per call and costs money per call.
     2	export async function generateSection(
     3	  company: string,
     4	  section: string,
     5	): Promise<string> {
     6	  const res = await fetch("https://api.example-llm.com/v1/generate", {
     7	    method: "POST",
     8	    body: JSON.stringify({ prompt: `Write the "${section}" section for ${company}` }),
     9	  });
    10	  return (await res.json()).text as string;
    11	}
    12	
    13	// Takes 1-3 s per call and costs money per call.
    14	export async function suggestTitle(sections: string[]): Promise<string> {
    15	  const res = await fetch("https://api.example-llm.com/v1/title", {
    16	    method: "POST",
    17	    body: JSON.stringify({ sections }),
    18	  });
    19	  return (await res.json()).title as string;
    20	}
=== src/queue.ts
     1	// Cloud Tasks queue "sections" (created in deploy.sh). One task per section.
     2	const QUEUE = process.env.SECTIONS_QUEUE!;
     3	
     4	export async function enqueueSection(reportId: string, section: string): Promise<void> {
     5	  await fetch(`https://cloudtasks.googleapis.com/v2/${QUEUE}/tasks`, {
     6	    method: "POST",
     7	    body: JSON.stringify({
     8	      task: {
     9	        httpRequest: {
    10	          url: `${process.env.WORKER_URL}/tasks/generate-section`,
    11	          body: btoa(JSON.stringify({ reportId, section })),
    12	        },
    13	      },
    14	    }),
    15	  });
    16	}
=== src/worker.ts
     1	import { generateSection } from "./llm";
     2	import { getReport, saveSection } from "./db";
     3	
     4	// Cloud Tasks HTTP target: POST /tasks/generate-section with { reportId, section }.
     5	export async function handleGenerateSection(req: Request): Promise<Response> {
     6	  const { reportId, section } = (await req.json()) as { reportId: string; section: string };
     7	  const report = await getReport(reportId);
     8	  if (!report) return new Response("gone", { status: 200 });
     9	  const body = await generateSection(report.company, section);
    10	  await saveSection(reportId, section, body);
    11	  return new Response("ok");
    12	}
